import gzip,glob,csv
def meta(f):
    rows={}
    for l in gzip.open(f,'rt',errors='replace'):
        if l.startswith('!series_matrix_table_begin'): break
        if l.startswith('!Sample_'):
            p=next(csv.reader([l.rstrip('\n')],delimiter='\t'))
            rows.setdefault(p[0],[]).append(p[1:])
    return rows
for f in sorted(glob.glob('studies/data/raw/*series_matrix*'))[2:]:
    print('=====',f)
    m=meta(f)
    print(list(m.keys()))
    ids=m['!Sample_geo_accession'][0]
    for i,g in enumerate(ids):
        print(g, m['!Sample_title'][0][i], '|', [c[i] for c in m.get('!Sample_characteristics_ch1',[])], '|', m['!Sample_source_name_ch1'][0][i])

